#!/usr/bin/env python3
"""fetch_osm_military.py — Pull OSM military facilities in Ukraine from Overpass API.

Queries Overpass for all military-tagged nodes/ways/relations within Ukraine's
bounding box, parses the GeoJSON-like response, and upserts into osm_military.

Idempotent: ON CONFLICT (osm_id, osm_type) DO UPDATE
Rate limit: Overpass is polite — single large query, no pagination needed.

Usage: python3 fetch_osm_military.py
"""

import json, sys, time, urllib.parse, urllib.request
from datetime import datetime, timezone

DB_CONTAINER = "ukraine-db"
DB_NAME = "ukraine_war"
DB_USER = "ukraine"

# Ukraine bounding box: sw lon, sw lat, ne lon, ne lat
BBOX = (44.3, 22.0, 52.4, 40.5)

UA = "UkraineWarTracker/1.0 (github.com/stansz/ukraine-war-tracker)"
OVERPASS_URL = "https://overpass-api.de/api/interpreter"

OVERPASS_QUERY = """[out:json][timeout:120];
(
  node["military"]({s},{w},{n},{e});
  way["military"]({s},{w},{n},{e});
  rel["military"]({s},{w},{n},{e});
  node["landuse"="military"]({s},{w},{n},{e});
  way["landuse"="military"]({s},{w},{n},{e});
  rel["landuse"="military"]({s},{w},{n},{e});
);
out body geom;
"""


def psql(sql: str) -> str:
    """Run SQL via podman exec and return stdout."""
    import subprocess
    r = subprocess.run(
        ["podman", "exec", "-i", DB_CONTAINER, "psql", "-U", DB_USER, "-d", DB_NAME, "-tA"],
        input=sql, capture_output=True, text=True, timeout=60,
    )
    if r.returncode != 0:
        print(f"  psql error: {r.stderr.strip()}", file=sys.stderr)
        sys.exit(1)
    return r.stdout.strip()


def centroid(geometry: dict) -> tuple[float, float]:
    """Compute centroid lat/lon from a GeoJSON geometry."""
    gtype = geometry.get("type", "")
    coords = geometry.get("coordinates", [])

    if gtype == "Point":
        return coords[1], coords[0]  # (lat, lon)

    if gtype == "LineString":
        lats = [p[1] for p in coords]
        lons = [p[0] for p in coords]
        return sum(lats) / len(lats), sum(lons) / len(lons)

    if gtype == "Polygon":
        ring = coords[0]  # outer ring
        lats = [p[1] for p in ring]
        lons = [p[0] for p in ring]
        return sum(lats) / len(lats), sum(lons) / len(lons)

    if gtype == "MultiPolygon":
        # Average of all outer ring centroids
        all_lats, all_lons = [], []
        for poly in coords:
            ring = poly[0]
            all_lats.extend(p[1] for p in ring)
            all_lons.extend(p[0] for p in ring)
        return sum(all_lats) / len(all_lats), sum(all_lons) / len(all_lons)

    # Fallback: Ukraine center
    return 49.0, 31.0


def overpass_to_geojson(el: dict) -> dict | None:
    """Convert an Overpass element to a GeoJSON geometry dict."""
    etype = el.get("type", "")

    if etype == "node":
        return {"type": "Point", "coordinates": [el["lon"], el["lat"]]}

    if etype == "way":
        geom = el.get("geometry")
        if not geom:
            return None
        coords = [[p["lon"], p["lat"]] for p in geom]
        # Check if closed (first == last)
        if len(coords) >= 4 and coords[0] == coords[-1]:
            return {"type": "Polygon", "coordinates": [coords]}
        return {"type": "LineString", "coordinates": coords}

    if etype == "relation":
        members = el.get("members", [])
        polygons = []
        for m in members:
            if m.get("type") != "way":
                continue
            geom = m.get("geometry")
            if not geom:
                continue
            coords = [[p["lon"], p["lat"]] for p in geom]
            if len(coords) >= 4 and coords[0] == coords[-1]:
                polygons.append([coords])

        if not polygons:
            return None
        if len(polygons) == 1:
            return {"type": "Polygon", "coordinates": polygons[0]}
        return {"type": "MultiPolygon", "coordinates": polygons}

    return None


def fetch_overpass() -> list[dict]:
    """Query Overpass API and return list of elements."""
    query = OVERPASS_QUERY.format(s=BBOX[0], w=BBOX[1], n=BBOX[2], e=BBOX[3])
    data = urllib.parse.urlencode({"data": query}).encode("utf-8")

    req = urllib.request.Request(
        OVERPASS_URL,
        data=data,
        headers={
            "Content-Type": "application/x-www-form-urlencoded",
            "User-Agent": UA,
            "Accept": "application/json",
        },
    )

    print(f"  Querying Overpass API...")
    t0 = time.time()
    try:
        resp = urllib.request.urlopen(req, timeout=130)
        raw = resp.read()
        result = json.loads(raw)
    except Exception as e:
        print(f"  Overpass query failed: {e}", file=sys.stderr)
        sys.exit(1)

    elapsed = time.time() - t0
    elements = result.get("elements", [])
    print(f"  Got {len(elements)} elements in {elapsed:.1f}s")

    return elements


def esc_sql(val) -> str:
    """Escape a value for safe SQL literal insertion."""
    if val is None:
        return "NULL"
    if isinstance(val, (int, float)):
        return str(val)
    return "'" + str(val).replace("'", "''") + "'"


def batch_upsert(rows: list[tuple], batch_size: int = 500) -> int:
    """Insert or update a batch of rows. Returns count of rows upserted."""
    if not rows:
        return 0

    total = 0
    for i in range(0, len(rows), batch_size):
        batch = rows[i:i + batch_size]
        values = []
        for r in batch:
            vals = ", ".join(esc_sql(v) for v in r)
            values.append(f"({vals})")

        sql = f"""
        INSERT INTO osm_military (osm_id, osm_type, name, military_type, geometry, lat, lon, tags, raw_json)
        VALUES {', '.join(values)}
        ON CONFLICT (osm_id, osm_type) DO UPDATE SET
            name = EXCLUDED.name,
            military_type = EXCLUDED.military_type,
            geometry = EXCLUDED.geometry,
            lat = EXCLUDED.lat,
            lon = EXCLUDED.lon,
            tags = EXCLUDED.tags,
            raw_json = EXCLUDED.raw_json,
            fetched_at = NOW()
        """
        psql(sql)
        total += len(batch)

    return total


def upsert_elements(elements: list[dict]) -> tuple[int, int, int]:
    """Upsert elements into osm_military. Returns (inserted, updated, skipped)."""
    rows = []
    skipped = 0

    for el in elements:
        osm_id = el.get("id")
        osm_type = el.get("type")
        tags = el.get("tags", {})

        geom = overpass_to_geojson(el)
        if geom is None:
            skipped += 1
            continue

        geom_json = json.dumps(geom, ensure_ascii=False)
        lat, lon = centroid(geom)

        name = tags.get("name", tags.get("official_name"))
        military_type = tags.get("military") or tags.get("landuse")
        tags_json = json.dumps(tags, ensure_ascii=False)
        raw_json = json.dumps(el, ensure_ascii=False)

        rows.append((osm_id, osm_type, name, military_type, geom_json, lat, lon, tags_json, raw_json))

    total = batch_upsert(rows)
    return total, 0, skipped  # updated tracked by ON CONFLICT, not separated


def main():
    # Skip if refreshed within 30 days — static data, Overpass is rate-limited
    last = psql("SELECT MAX(fetched_at) FROM osm_military;")
    if last:
        try:
            last_dt = datetime.fromisoformat(last)
            if last_dt.tzinfo is None:
                last_dt = last_dt.replace(tzinfo=timezone.utc)
            age = (datetime.now(timezone.utc) - last_dt).days
            if age < 30:
                print(f"  Skipped — last refreshed {last} ({age}d ago) < 30d threshold")
                return 0
        except ValueError:
            pass  # malformed date — proceed with fetch

    print(f"=== fetch_osm_military.py — {datetime.now(timezone.utc).strftime('%Y-%m-%d %H:%M:%S')} UTC ===")

    elements = fetch_overpass()
    upserted, _, skipped = upsert_elements(elements)

    # Summary
    total = psql("SELECT COUNT(*) FROM osm_military;")
    print(f"\n  Upserted:  {upserted}")
    print(f"  Skipped:   {skipped}")
    print(f"  Total DB:  {total}")
    print("  DONE")


if __name__ == "__main__":
    main()
